    @Test
    void deprecatedConvertOfdColorSupportsNumericRgbArray() {
        com.itextpdf.kernel.colors.Color color = CommonUtil.convertOfdColor(new ST_Array("255", "128", "0"));
        assertNotNull(color);
        assertArrayEquals(new float[]{1f, 128f / 255f, 0f}, color.getColorValue(), 1e-6f);
    }

    private static void assertMatricesEqual(Matrix expected, Matrix actual) {
        assertEquals(expected.getRowCount(), actual.getRowCount());
        assertEquals(expected.getColumnCount(), actual.getColumnCount());
        for (int row = 0; row < expected.getRowCount(); row++) {
            for (int column = 0; column < expected.getColumnCount(); column++) {
                assertEquals(expected.getAsDouble(row, column), actual.getAsDouble(row, column), 1e-6);
            }
        }
    }

    private static void assertBoxEquals(ST_Box expected, ST_Box actual) {
        assertNotNull(actual);
        assertEquals(expected.getTopLeftX(), actual.getTopLeftX(), EPS);
        assertEquals(expected.getTopLeftY(), actual.getTopLeftY(), EPS);
        assertEquals(expected.getWidth(), actual.getWidth(), EPS);
        assertEquals(expected.getHeight(), actual.getHeight(), EPS);
    }
}
package org.ofdrw.converter.utils;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.File;
import java.io.IOException;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.*;

class FontUtilsTest {

    @TempDir
    Path tempDir;

    @Test
    void addSystemFontMappingMakesFontPathRetrievableByNameAndFamily() throws IOException {
        File font = tempDir.resolve("mapping-test.ttf").toFile();
        assertTrue(font.createNewFile());

        FontUtils.addSystemFontMapping("FontUtilsTestFamily", "FontUtilsTestFont", font.getAbsolutePath());

        assertEquals(font.getAbsolutePath(), FontUtils.getSystemFontPath("FontUtilsTestFamily", "FontUtilsTestFont"));
        assertEquals(font.getAbsolutePath(), FontUtils.getSystemFontPath("FontUtilsTestFamily", null));
        assertEquals(font.getAbsolutePath(), FontUtils.getSystemFontPath(null, "FontUtilsTestFont"));
    }

    @Test
    void addAliasMappingResolvesAliasToMappedFontPath() throws IOException {
        File font = tempDir.resolve("alias-target.ttf").toFile();
        assertTrue(font.createNewFile());

        FontUtils.addSystemFontMapping("AliasTargetFamily", "AliasTargetFont", font.getAbsolutePath());
        FontUtils.addAliasMapping("OriginalFamily", "OriginalFont", "AliasTargetFamily", "AliasTargetFont");

        assertEquals(font.getAbsolutePath(), FontUtils.getSystemFontPath("OriginalFamily", "OriginalFont"));
    }

    @Test
    void getSystemFontPathReturnsNullWhenNothingIsMapped() {
        assertNull(FontUtils.getSystemFontPath("NoSuchFamily", "NoSuchFont"));
        assertNull(FontUtils.getSystemFontPath(null, null));
    }

    @Test
    void scanFontDirDoesNotFailForEmptyDirectory() {
        assertDoesNotThrow(() -> FontUtils.scanFontDir(tempDir.toFile()));
    }

    @Test
    void loadFontDoesNotFailForNonFontFile() throws IOException {
        File invalid = tempDir.resolve("invalid-font.ttf").toFile();
        assertTrue(invalid.createNewFile());
        assertDoesNotThrow(() -> FontUtils.loadFont(invalid));
    }
}
package org.ofdrw.converter.utils;

import org.junit.jupiter.api.Test;
import org.ofdrw.converter.point.Tuple2;
import org.ujmp.core.Matrix;

import java.awt.geom.AffineTransform;
import java.awt.geom.Point2D;

import static org.junit.jupiter.api.Assertions.*;

class MatrixUtilsTest {

    private static final double EPS = 1e-9;

    @Test
    void baseIsThreeByThreeIdentityMatrix() {
        Matrix matrix = MatrixUtils.base();
        assertEquals(3, matrix.getRowCount());
        assertEquals(3, matrix.getColumnCount());
        assertEquals(1.0, matrix.getAsDouble(0, 0), EPS);
        assertEquals(1.0, matrix.getAsDouble(1, 1), EPS);
        assertEquals(1.0, matrix.getAsDouble(2, 2), EPS);
        assertEquals(0.0, matrix.getAsDouble(0, 1), EPS);
        assertEquals(0.0, matrix.getAsDouble(1, 0), EPS);
        assertEquals(0.0, matrix.getAsDouble(0, 2), EPS);
    }

    @Test
    void createPlacesValuesInRowMajorAffineLayout() {
        Matrix matrix = MatrixUtils.create(1, 2, 3, 4, 5, 6);
        assertEquals(1.0, matrix.getAsDouble(0, 0), EPS);
        assertEquals(2.0, matrix.getAsDouble(0, 1), EPS);
        assertEquals(3.0, matrix.getAsDouble(1, 0), EPS);
        assertEquals(4.0, matrix.getAsDouble(1, 1), EPS);
        assertEquals(5.0, matrix.getAsDouble(2, 0), EPS);
        assertEquals(6.0, matrix.getAsDouble(2, 1), EPS);
        assertEquals(1.0, matrix.getAsDouble(2, 2), EPS);
    }

    @Test
    void ctmCreatesMatrixFromSixValues() {
        Matrix matrix = MatrixUtils.ctm(1d, 2d, 3d, 4d, 5d, 6d);
        assertEquals(1.0, matrix.getAsDouble(0, 0), EPS);
        assertEquals(2.0, matrix.getAsDouble(0, 1), EPS);
        assertEquals(3.0, matrix.getAsDouble(1, 0), EPS);
        assertEquals(4.0, matrix.getAsDouble(1, 1), EPS);
        assertEquals(5.0, matrix.getAsDouble(2, 0), EPS);
        assertEquals(6.0, matrix.getAsDouble(2, 1), EPS);
    }

    @Test
    void scaleAndMoveComposeWithTheSuppliedMatrix() {
        Matrix scaled = MatrixUtils.scale(MatrixUtils.base(), 2, 3);
        assertEquals(2.0, scaled.getAsDouble(0, 0), EPS);
        assertEquals(3.0, scaled.getAsDouble(1, 1), EPS);

        Matrix moved = MatrixUtils.move(MatrixUtils.base(), 10, 20);
        assertEquals(10.0, moved.getAsDouble(2, 0), EPS);
        assertEquals(20.0, moved.getAsDouble(2, 1), EPS);
        assertEquals(1.0, moved.getAsDouble(0, 0), EPS);
    }

    @Test
    void imageMatrixBuildsReflectionAcrossXAxis() {
        Matrix reflected = MatrixUtils.imageMatrix(MatrixUtils.base(), 0, 1, 0);
        assertEquals(1.0, reflected.getAsDouble(0, 0), EPS);
        assertEquals(0.0, reflected.getAsDouble(0, 1), EPS);
        assertEquals(0.0, reflected.getAsDouble(1, 0), EPS);
        assertEquals(-1.0, reflected.getAsDouble(1, 1), EPS);
        assertEquals(0.0, reflected.getAsDouble(2, 0), EPS);
        assertEquals(0.0, reflected.getAsDouble(2, 1), EPS);
        assertEquals(1.0, reflected.getAsDouble(2, 2), EPS);
    }

    @Test
    void imageMatrixBuildsReflectionAcrossYAxis() {
        Matrix reflected = MatrixUtils.imageMatrix(MatrixUtils.base(), 1, 0, 0);
        assertEquals(-1.0, reflected.getAsDouble(0, 0), EPS);
        assertEquals(0.0, reflected.getAsDouble(0, 1), EPS);
        assertEquals(0.0, reflected.getAsDouble(1, 0), EPS);
        assertEquals(1.0, reflected.getAsDouble(1, 1), EPS);
        assertEquals(1.0, reflected.getAsDouble(2, 2), EPS);
    }

    @Test
    void createAffineTransformPreservesScaleAndTranslation() {
        AffineTransform transform = MatrixUtils.createAffineTransform(MatrixUtils.create(2, 0, 0, 3, 10, 20));
        Point2D transformed = transform.transform(new Point2D.Double(1, 1), null);
        assertEquals(12.0, transformed.getX(), EPS);
        assertEquals(23.0, transformed.getY(), EPS);
    }

    @Test
    void pointTransformAppliesAffineMatrixToPoint() {
        Tuple2<Double, Double> point = MatrixUtils.pointTransform(
                MatrixUtils.create(2, 0, 0, 3, 10, 20), 1d, 2d);
        assertEquals(12.0, point.getFirst(), EPS);
        assertEquals(26.0, point.getSecond(), EPS);
    }

    @Test
    void leftTopReturnsTranslationForUnrotatedPositiveScale() {
        Tuple2<Double, Double> corner = MatrixUtils.leftTop(MatrixUtils.create(2, 0, 0, 3, 10, 20));
        assertEquals(10.0, corner.getFirst(), EPS);
        assertEquals(20.0, corner.getSecond(), EPS);
    }
}
package org.ofdrw.converter.utils;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class OSinfoTest {

    @Test
    void platformDescriptionsMatchTheirEnumNames() {
        assertEquals("any", OSinfo.EPlatform.Any.toString());
        assertEquals("Linux", OSinfo.EPlatform.Linux.toString());
        assertEquals("Mac OS", OSinfo.EPlatform.Mac_OS.toString());
        assertEquals("Mac OS X", OSinfo.EPlatform.Mac_OS_X.toString());
        assertEquals("Windows", OSinfo.EPlatform.Windows.toString());
        assertEquals("OS/2", OSinfo.EPlatform.OS2.toString());
        assertEquals("OpenVMS", OSinfo.EPlatform.OpenVMS.toString());
        assertEquals("Others", OSinfo.EPlatform.Others.toString());
    }

    @Test
    void detectionMethodsAgreeWithTheReportedPlatform() {
        String osName = System.getProperty("os.name").toLowerCase();
        if (osName.contains("linux")) {
            assertTrue(OSinfo.isLinux());
            assertFalse(OSinfo.isWindows());
            assertSame(OSinfo.EPlatform.Linux, OSinfo.getOSname());
        } else if (osName.contains("windows")) {
            assertTrue(OSinfo.isWindows());
            assertFalse(OSinfo.isLinux());
            assertSame(OSinfo.EPlatform.Windows, OSinfo.getOSname());
        } else {
            assertNotNull(OSinfo.getOSname());
        }
    }
}
package org.ofdrw.converter.utils;

