import static org.junit.jupiter.api.Assertions.*;

class PointUtilPathTest {

    private static final double EPS = 1e-3;

    @Test
    void convertPathAbbreviatedDataParsesEverySupportedOperator() {
        List<PathPoint> points = PointUtil.convertPathAbbreviatedDatatoPoint(
                "M 10 20 L 30 40 C 1 2 3 4 5 6 S 50 60 B 1 2 3 4 5 6 Q 7 8 9 10 A 11 12 13 14 15 16 17");

        assertEquals(7, points.size());
        assertEquals("M", points.get(0).type);
        assertEquals(10f, points.get(0).x1, 1e-6f);
        assertEquals(20f, points.get(0).y1, 1e-6f);
        assertEquals("L", points.get(1).type);
        assertEquals(30f, points.get(1).x1, 1e-6f);
        assertEquals(40f, points.get(1).y1, 1e-6f);
        assertEquals("C", points.get(2).type);
        assertEquals(0f, points.get(2).x1, 1e-6f);
        assertEquals("S", points.get(3).type);
        assertEquals(50f, points.get(3).x1, 1e-6f);
        assertEquals(60f, points.get(3).y1, 1e-6f);
        assertEquals("B", points.get(4).type);
        assertEquals(1f, points.get(4).x1, 1e-6f);
        assertEquals(6f, points.get(4).y3, 1e-6f);
        assertEquals("Q", points.get(5).type);
        assertEquals(7f, points.get(5).x1, 1e-6f);
        assertEquals(10f, points.get(5).y2, 1e-6f);
        assertEquals("A", points.get(6).type);
        assertEquals(11f, points.get(6).rx, 1e-6f);
        assertEquals(12f, points.get(6).ry, 1e-6f);
        assertEquals(13f, points.get(6).rotation, 1e-6f);
        assertEquals(14f, points.get(6).arc, 1e-6f);
        assertEquals(15f, points.get(6).sweep, 1e-6f);
        assertEquals(16f, points.get(6).x, 1e-6f);
        assertEquals(17f, points.get(6).y, 1e-6f);
    }

    @Test
    void convertPathAbbreviatedDataReturnsEmptyForNullAndEmptyInput() {
        assertTrue(PointUtil.convertPathAbbreviatedDatatoPoint(null).isEmpty());
        assertTrue(PointUtil.convertPathAbbreviatedDatatoPoint("").isEmpty());
    }

    @Test
    void calPathPointConvertsLineAndCurveCoordinatesAndSkipsOtherOperators() {
        List<PathPoint> source = new ArrayList<>();
        source.add(new PathPoint("M", 10, 20, 0, 0, 0, 0));
        source.add(new PathPoint("L", 30, 40, 0, 0, 0, 0));
        source.add(new PathPoint("B", 1, 2, 3, 4, 5, 6));
        source.add(new PathPoint("Q", 7, 8, 9, 10, 0, 0));
        source.add(new PathPoint("A", 11, 12, 13, 14, 15, 16, 17));

        List<PathPoint> result = PointUtil.calPathPoint(source);

        assertEquals(3, result.size());
        assertEquals(CommonUtil.converterDpi(10), result.get(0).x1, EPS);
        assertEquals(CommonUtil.converterDpi(20), result.get(0).y1, EPS);
        assertEquals(CommonUtil.converterDpi(30), result.get(1).x1, EPS);
        assertEquals(CommonUtil.converterDpi(40), result.get(1).y1, EPS);
        assertEquals(CommonUtil.converterDpi(1), result.get(2).x1, EPS);
        assertEquals(CommonUtil.converterDpi(2), result.get(2).y1, EPS);
        assertEquals(CommonUtil.converterDpi(3), result.get(2).x2, EPS);
        assertEquals(CommonUtil.converterDpi(4), result.get(2).y2, EPS);
        assertEquals(CommonUtil.converterDpi(5), result.get(2).x3, EPS);
        assertEquals(CommonUtil.converterDpi(6), result.get(2).y3, EPS);
    }

    @Test
    void calTextPointAdvancesByDeltaXAndDeltaY() {
        TextCode textCode = new TextCode()
                .setCoordinate(10.0, 20.0)
                .setContent("AB");
        textCode.setDeltaX(new ST_Array("5"));
        textCode.setDeltaY(new ST_Array("2"));

        List<TextCodePoint> points = PointUtil.calTextPoint(Collections.singletonList(textCode));

        assertEquals(2, points.size());
        assertEquals(CommonUtil.converterDpi(10), points.get(0).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(20), points.get(0).getY(), EPS);
        assertEquals("A", points.get(0).getText());
        assertEquals(CommonUtil.converterDpi(15), points.get(1).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(22), points.get(1).getY(), EPS);
        assertEquals("B", points.get(1).getText());
    }

    @Test
    void calTextPointUsesSamePositionWhenNoDeltasExist() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("AB");
        List<TextCodePoint> points = PointUtil.calTextPoint(Collections.singletonList(textCode));

        assertEquals(2, points.size());
        assertEquals(points.get(0).getX(), points.get(1).getX(), 1e-9);
        assertEquals(points.get(0).getY(), points.get(1).getY(), 1e-9);
    }

    @Test
