    @Test
    void calPdfPathPointAppliesOriginFixScaleAndBoundary() {
        List<PathPoint> fixed = PointUtil.calPdfPathPoint(100, 200, null,
                Collections.singletonList(new PathPoint("M", 10, 20, 0, 0, 0, 0)),
                false, null, null, null, true);
        assertEquals(CommonUtil.converterDpi(10), fixed.get(0).x1, EPS);
        assertEquals(CommonUtil.converterDpi(180), fixed.get(0).y1, EPS);

        List<PathPoint> scaled = PointUtil.calPdfPathPoint(100, 200, null,
                Collections.singletonList(new PathPoint("M", 10, 20, 0, 0, 0, 0)),
                false, null, null, null, false, 2.0);
        assertEquals(CommonUtil.converterDpi(20), scaled.get(0).x1, EPS);
        assertEquals(CommonUtil.converterDpi(40), scaled.get(0).y1, EPS);

        List<PathPoint> offset = PointUtil.calPdfPathPoint(100, 200, new ST_Box(5, 7, 50, 50),
                Collections.singletonList(new PathPoint("M", 10, 20, 0, 0, 0, 0)),
                false, null, null, null, false);
        assertEquals(CommonUtil.converterDpi(15), offset.get(0).x1, EPS);
        assertEquals(CommonUtil.converterDpi(27), offset.get(0).y1, EPS);
    }

    @Test
    void calPdfPathPointAppliesCtmBeforeBoundaryOffset() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(100, 200, new ST_Box(1, 2, 50, 50),
                Collections.singletonList(new PathPoint("M", 10, 20, 0, 0, 0, 0)),
                true, new ST_Array("1", "0", "0", "1", "100", "200"), null, null, false);

        assertEquals(CommonUtil.converterDpi(111), result.get(0).x1, EPS);
        assertEquals(CommonUtil.converterDpi(222), result.get(0).y1, EPS);
    }

    @Test
    void calPdfPathPointConvertsBezierQuadraticAndArcPoints() {
        List<PathPoint> bezier = PointUtil.calPdfPathPoint(100, 100, null,
                Collections.singletonList(new PathPoint("B", 1, 2, 3, 4, 5, 6)),
                false, null, null, null, false);
        assertEquals(CommonUtil.converterDpi(1), bezier.get(0).x1, EPS);
        assertEquals(CommonUtil.converterDpi(2), bezier.get(0).y1, EPS);
        assertEquals(CommonUtil.converterDpi(3), bezier.get(0).x2, EPS);
        assertEquals(CommonUtil.converterDpi(4), bezier.get(0).y2, EPS);
        assertEquals(CommonUtil.converterDpi(5), bezier.get(0).x3, EPS);
        assertEquals(CommonUtil.converterDpi(6), bezier.get(0).y3, EPS);

        List<PathPoint> quadratic = PointUtil.calPdfPathPoint(100, 100, null,
                Collections.singletonList(new PathPoint("Q", 1, 2, 3, 4, 0, 0)),
                false, null, null, null, false);
        assertEquals(CommonUtil.converterDpi(1), quadratic.get(0).x1, EPS);
        assertEquals(CommonUtil.converterDpi(2), quadratic.get(0).y1, EPS);
        assertEquals(CommonUtil.converterDpi(3), quadratic.get(0).x2, EPS);
        assertEquals(CommonUtil.converterDpi(4), quadratic.get(0).y2, EPS);

        List<PathPoint> arc = PointUtil.calPdfPathPoint(100, 100, null,
                Collections.singletonList(new PathPoint("A", 11, 12, 13, 14, 15, 16, 17)),
                false, null, null, null, false);
        assertEquals(CommonUtil.converterDpi(11), arc.get(0).rx, EPS);
        assertEquals(CommonUtil.converterDpi(12), arc.get(0).ry, EPS);
        assertEquals(13f, arc.get(0).rotation, 1e-6f);
        assertEquals(14f, arc.get(0).arc, 1e-6f);
        assertEquals(15f, arc.get(0).sweep, 1e-6f);
        assertEquals(CommonUtil.converterDpi(16), arc.get(0).x, EPS);
        assertEquals(CommonUtil.converterDpi(17), arc.get(0).y, EPS);
    }

    @Test
    void calPdfPathPointCombinesCompositeObjectBoundary() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(100, 200, new ST_Box(1, 1, 50, 50),
                Collections.singletonList(new PathPoint("M", 2, 3, 0, 0, 0, 0)),
                false, null, new ST_Box(10, 20, 50, 50), null, false);

        assertEquals(CommonUtil.converterDpi(13), result.get(0).x1, EPS);
        assertEquals(CommonUtil.converterDpi(24), result.get(0).y1, EPS);
    }

    @Test
    void calPdfPathPointUsesLegacy300DpiScaleForAbsoluteFoxitPaths() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(100, 100, new ST_Box(0, 0, 100, 100),
                Collections.singletonList(new PathPoint("M", 1000, 1000, 0, 0, 0, 0)),
                true, ST_Array.unitCTM(), null, null, false);

        assertEquals(240.0, result.get(0).x1, 1e-2);
        assertEquals(240.0, result.get(0).y1, 1e-2);
    }
}

package org.ofdrw.converter.utils;

import org.junit.jupiter.api.Test;
import org.ofdrw.converter.point.TextCodePoint;
import org.ofdrw.core.basicType.ST_Array;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.text.CT_CGTransform;
import org.ofdrw.core.text.TextCode;

import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class PointUtilTextTest {

    private static final double EPS = 1e-3;

    @Test
    void simpleTextCoordinateConvertsEachCharacterPosition() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("AB");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0);

        assertEquals(2, points.size());
        assertEquals(CommonUtil.converterDpi(10), points.get(0).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(20), points.get(0).getY(), EPS);
        assertEquals("A", points.get(0).getText());
        assertEquals(CommonUtil.converterDpi(10), points.get(1).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(20), points.get(1).getY(), EPS);
        assertEquals("B", points.get(1).getText());
    }

    @Test
    void simpleTextCoordinateAdvancesByDeltaXAndDeltaY() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("AB");
        textCode.setDeltaX(new ST_Array("5"));
        textCode.setDeltaY(new ST_Array("2"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0);

        assertEquals(CommonUtil.converterDpi(10), points.get(0).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(20), points.get(0).getY(), EPS);
        assertEquals(CommonUtil.converterDpi(15), points.get(1).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(22), points.get(1).getY(), EPS);
    }

    @Test
    void simpleTextCoordinateAppliesOriginFixScaleAndBoundary() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("A");

        List<TextCodePoint> fixed = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode), false, null, true, 1.0);
        assertEquals(CommonUtil.converterDpi(180), fixed.get(0).getY(), EPS);

        List<TextCodePoint> scaledAndOffset = PointUtil.calPdfTextCoordinate(
                100, 200, new ST_Box(5, 7, 50, 50), 12f,
                Collections.singletonList(textCode), false, null, false, 2.0);
        assertEquals(CommonUtil.converterDpi(25), scaledAndOffset.get(0).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(47), scaledAndOffset.get(0).getY(), EPS);
    }

    @Test
    void simpleTextCoordinateAppliesCtmTranslationOnceAndDeltasAsVectors() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("AB");
        textCode.setDeltaX(new ST_Array("5"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode), true,
                new ST_Array("1", "0", "0", "1", "100", "200"), false, 1.0);

        assertEquals(CommonUtil.converterDpi(110), points.get(0).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(220), points.get(0).getY(), EPS);
        assertEquals(CommonUtil.converterDpi(115), points.get(1).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(220), points.get(1).getY(), EPS);
    }

    @Test
    void simpleTextCoordinateNormalizesXmlEntitiesAndRemovesLineFeeds() {
        TextCode textCode = new TextCode().setCoordinate(0.0, 0.0)
                .setContent("A&amp;B&nbsp;C&copy;\nD");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0);

        assertEquals("A&B CD", joinedText(points));
    }

    @Test
    void simpleTextCoordinateDefaultsMissingCoordinatesToZero() {
        TextCode textCode = new TextCode().setContent("A");
        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0);

        assertEquals(1, points.size());
        assertEquals(0.0, points.get(0).getX(), EPS);
        assertEquals(0.0, points.get(0).getY(), EPS);
    }

    @Test
    void simpleTextCoordinateReturnsEmptyListForNoTextCodes() {
        assertTrue(PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.emptyList(), false, null, false, 1.0).isEmpty());
    }

    @Test
    void transformerOverloadProducesCharacterPointsWithoutGlyphTransforms() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("AB");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.emptyList(), null, null, false, null, false, 1.0);

        assertEquals(2, points.size());
        assertEquals("A", points.get(0).getText());
        assertEquals("B", points.get(1).getText());
        assertNull(points.get(0).getGlyph());
        assertEquals(CommonUtil.converterDpi(10), points.get(1).getX(), EPS);
    }

    @Test
    void transformerOverloadAssignsGlyphIndexesFromCgTransform() {
        TextCode textCode = new TextCode().setCoordinate(0.0, 0.0).setContent("AB");
        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(2)
                .setGlyphCount(2)
                .setGlyphs(new ST_Array("5", "6"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.singletonList(transform), null, null, false, null, false, 1.0);

        assertEquals(2, points.size());
        assertEquals("5", points.get(0).getGlyph());
        assertEquals("6", points.get(1).getGlyph());
    }

    @Test
    void transformerOverloadAppliesCompositeObjectCtm() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("A");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.emptyList(), null, new ST_Array("1", "0", "0", "1", "10", "20"),
                false, null, false, 1.0);

        assertEquals(CommonUtil.converterDpi(20), points.get(0).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(40), points.get(0).getY(), EPS);
    }

    @Test
    void transformerOverloadAppliesBoundaryOffset() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("A");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, new ST_Box(1, 2, 50, 50), 12f, Collections.singletonList(textCode),
                Collections.emptyList(), null, null, false, null, false, 1.0);

        assertEquals(CommonUtil.converterDpi(11), points.get(0).getX(), EPS);
        assertEquals(CommonUtil.converterDpi(22), points.get(0).getY(), EPS);
    }

    @Test
    void elevenArgumentOverloadDelegatesToExplicitScaleOverload() {
        TextCode textCode = new TextCode().setCoordinate(10.0, 20.0).setContent("AB");
        textCode.setDeltaX(new ST_Array("5"));

        List<TextCodePoint> delegated = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.emptyList(), null, null, false, null, false);
        List<TextCodePoint> explicit = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.emptyList(), null, null, false, null, false, 1.0);

        assertEquals(explicit.size(), delegated.size());
        for (int i = 0; i < explicit.size(); i++) {
            assertEquals(explicit.get(i).getX(), delegated.get(i).getX(), 1e-9);
            assertEquals(explicit.get(i).getY(), delegated.get(i).getY(), 1e-9);
            assertEquals(explicit.get(i).getText(), delegated.get(i).getText());
        }
    }

    private static String joinedText(List<TextCodePoint> points) {
        StringBuilder text = new StringBuilder();
        for (TextCodePoint point : points) {
            text.append(point.getText());
        }
        return text.toString();
    }
}

package org.ofdrw.converter.utils;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class StringUtilsTest {

    @Test
    void isBlankTreatsOnlyNullAndEmptyAsBlank() {
        assertTrue(StringUtils.isBlank(null));
        assertTrue(StringUtils.isBlank(""));
        assertFalse(StringUtils.isBlank(" "));
        assertFalse(StringUtils.isBlank("\n"));
        assertFalse(StringUtils.isBlank("a"));
    }

    @Test
    void removeNewlineReturnsEmptyStringForNull() {
        assertEquals("", StringUtils.removeNewline(null));
    }

    @Test
    void removeNewlineDropsLineFeedAndNullCharacters() {
        assertEquals("ab", StringUtils.removeNewline("a\nb"));
        assertEquals("ab", StringUtils.removeNewline("\u0000a\u0000b\u0000"));
    }

    @Test
    void removeNewlineKeepsOtherCharacterTypes() {
        assertEquals("a\rb", StringUtils.removeNewline("a\rb"));
        assertEquals("a\tb", StringUtils.removeNewline("a\tb"));
        assertEquals("中文", StringUtils.removeNewline("中文"));
    }
}
